def _index(graph):
    nodes={n.get("id"):n for n in graph.get("nodes",[]) if isinstance(n,dict) and n.get("id")}
    edges=[]; adj=collections.defaultdict(list); incoming=collections.defaultdict(list)
    for e in graph.get("edges",[]):
