    return nodes,edges,adj,incoming

def _shortest_path(adj, starts, goals):
    goals=set(goals); q=collections.deque((s,[s]) for s in starts); seen=set(starts)
    while q:
        node,path=q.popleft()
        if node in goals: return path
        for nxt,_ in adj.get(node,[]):
            if nxt not in seen:
                seen.add(nxt); q.append((nxt,path+[nxt]))
    return []

