    if not isinstance(req,dict) or not isinstance(req.get("requirement_id"),str) or not req["requirement_id"].strip():
        raise ValueError("requirement_id is required")
    nodes,edges,adj,incoming=_index(graph)
    entries=_require_list(req,"entrypoint_nodes")
    impls=_require_list(req,"implementation_nodes")
    tests=_require_list(req,"test_nodes")
    missing=req.get("missing_components",[]); actionable=req.get("actionable_reasons",[])
    if not isinstance(missing,list) or not isinstance(actionable,list): raise ValueError("missing_components/actionable_reasons must be lists")
    for key,vals in (("entrypoint_nodes",entries),("implementation_nodes",impls),("test_nodes",tests)):
        unknown=[x for x in vals if x not in nodes]
        if unknown: raise ValueError(f"{key} contains unknown graph nodes: {unknown}")
    base={"requirement_id":req["requirement_id"],"status":None,"evidence":[],"production_path":[],"reason":""}
    if missing or not impls:
        base.update(status="INCOMPLETE",reason="Required implementation components are missing",evidence=list(missing))
        return base
    test_set=set(tests)
    production_callers=[]
    for target in impls:
        for source,e in incoming.get(target,[]):
            if source in test_set: continue
            if e.get("relation") in CALLER_RELATIONS:
                production_callers.append((source,target,e.get("relation")))
    if not production_callers:
        base.update(status="UNWIRED",reason="Implementation exists but has no non-test production caller",evidence=[f"implementation:{x}" for x in impls])
        return base
    path=_shortest_path(adj,entries,impls) if entries else []
    if not path:
        base.update(status="UNREACHABLE",reason="Implementation has callers but no directed path from a declared production entrypoint",evidence=[f"caller:{s}->{t}:{r}" for s,t,r in production_callers])
        return base
    base["production_path"]=path
    if not tests:
        base.update(status="UNTESTED",reason="Production path is reachable but no focused test evidence is mapped",evidence=["path:"+" -> ".join(path)])
        return base
    if actionable:
